INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('삿포로 시계탑', '札幌市時計台', 'HISTORIC', '北海道', '札幌市中央区', 43.062600, 141.353600, 'FIXED', '08:45', '17:10', NULL, '입관 17:00까지. 12/29~1/3 휴관', '200엔 (고교생 이하 무료)', '정식 명칭은 옛 삿포로 농학교 연무장. 클라크 박사의 구상으로 1878년에 지었고, 매 정시 종소리로 시간을 알리는 현존 일본 최고(最古)의 시계탑이다. 국가 중요문화재.', '정면 맞은편 빌딩 2층에 무료 촬영 테라스가 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('삿포로 TV탑', 'さっぽろテレビ塔', 'VIEWPOINT', '北海道', '札幌市中央区', 43.061100, 141.356400, 'FIXED', '09:00', '22:00', NULL, '최종 입장 21:50. 부정기 휴무', '1,200엔 (초중학생 600엔, 미취학 무료)', '1956년에 세운 오도리 공원 동쪽 끝의 빨간 랜드마크. 엘리베이터로 약 60초 오르면 지상 약 90m 전망대에서 360도 파노라마가 펼쳐진다.', '남동쪽의 "고와소(무서운 창)"는 바닥부터 천장까지 통유리라 아찔하다. 겨울 일루미네이션 시즌이 특히 좋다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('모이와산 로프웨이', '札幌もいわ山ロープウェイ', 'VIEWPOINT', '北海道', '札幌市中央区', 43.035100, 141.322800, 'FIXED', '10:30', '22:00', NULL, '4~11월 기준(상행 막차 21:30), 12~3월 11:00~22:00. 악천후·정비 운휴 있음', '로프웨이+미니 케이블카 왕복 1,800엔 (어린이 900엔)', '표고 531m 모이와산 정상까지 로프웨이와 미니 케이블카로 오른다. "일본 신 3대 야경"으로 꼽힌 삿포로 야경 명소.', '노면전차 "로프웨이 이리구치" 정류장에서 산기슭역까지 무료 셔틀버스가 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('홋카이도 신궁', '北海道神宮', 'SHRINE_TEMPLE', '北海道', '札幌市中央区', 43.054500, 141.307900, 'FIXED', '06:00', '17:00', NULL, '4~10월 기준. 3월 7:00~17:00, 11~12월·1/8~2월 7:00~16:00. 12/31~1/7은 개문 시간 변경', '무료', '1869년 메이지 천황의 조칙으로 개척 삼신을 모신 홋카이도의 총진수. 마루야마 공원과 붙은 넓은 숲에 있다.', '봄엔 벚꽃과 매화가 거의 동시에 피고, 운이 좋으면 에조다람쥐를 만날 수 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('니조 시장', '二条市場', 'MARKET', '北海道', '札幌市中央区', 43.057300, 141.358400, 'FIXED', '07:00', '18:00', NULL, '음식점가는 6:00~21:00. 가게마다 다름', '무료', '메이지 초기 이시카리 해변 어부들이 생선을 팔기 시작한 데서 출발한 삿포로 시민의 부엌. 게·가리비 같은 해산물 토산품이 많다.', '아침이나 점심으로 해산물 덮밥을 먹기 좋고, 안쪽 "노렌 요코초"엔 개성 있는 음식점이 모여 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('오타루 운하', '小樽運河', 'HISTORIC', '北海道', '小樽市', 43.198900, 141.001800, 'ALWAYS', NULL, NULL, NULL, '상시 산책 가능', '무료', '1923년에 완성한 운하. 석조 창고가 늘어선 산책로가 정비돼 있고, 해 질 녘엔 63개 가스등이 켜진다.', '2월 "오타루 유키아카리노미치" 기간엔 운하에 촛불이 떠서 더 환상적이다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('오타루 오르골당 본관', '小樽オルゴール堂 本館', 'HISTORIC', '北海道', '小樽市', 43.191500, 141.007700, 'FIXED', '09:00', '18:00', NULL, '여름철 금·토요일·공휴일 전날은 19:00까지. 무휴', NULL, '1915년 지은 벽돌 건물을 쓰는 오르골 전문점. 3,000종이 넘는 오르골이 모여 있다.', '입구 앞 세계 최대 증기시계가 15분마다 증기로 멜로디를 연주한다. 2호관에선 하루 6번 무료 미니 콘서트가 열린다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('오타루 산카쿠 시장', '小樽三角市場', 'MARKET', '北海道', '小樽市', 43.198000, 140.994300, 'FIXED', '06:00', '17:00', NULL, '식당은 7:00부터, 가게마다 다름. 1/1 휴무', '무료', 'JR 오타루역 바로 옆, 삼각형 땅과 지붕에서 이름을 딴 시장. 오타루 근해 성게·연어알을 파는 가게와 식당이 모여 있다.', '성게 덮밥·연어알 덮밥을 먹을 수 있고, 대부분 가게가 전국 택배를 해 준다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('아사히야마 동물원', '旭川市旭山動物園', 'AMUSEMENT', '北海道', '旭川市', 43.768600, 142.479300, 'FIXED', '09:30', '17:15', NULL, '2026년: 4/29~10/15 9:30~17:15, 10/16~11/3 9:30~16:30(최종 입원 16:00), 11/11~2027/4/7 10:30~15:30(최종 입원 15:00). 8/10~16은 21:00까지. 4/8~28, 11/4~10, 12/30~1/1 휴원', '1,000엔 (중학생 이하 무료)', '동물의 자연스러운 행동을 보여 주는 "행동 전시"로 유명한 일본 최북단 동물원.', '북극곰 다이빙과 원통 수조를 오가는 바다표범이 인기이고, 겨울엔 펭귄 산책을 볼 수 있다.', NULL, NULL, DATE '2026-11-22', NULL);
INSERT INTO spots (name, name_ja, kind, prefecture, city, lat, lng, hours_kind, open_time, close_time, closed_days, hours_note, fee_note, description, tips, google_place_id, official_url, verified_at, image_url) VALUES ('오토코야마 술 만들기 자료관', '男山酒造り資料館', 'MUSEUM', '北海道', '旭川市', 43.787400, 142.437600, 'FIXED', '09:00', '17:00', NULL, '12/31~1/3 휴관', '무료', '350년 넘는 역사의 아사히카와 지역 술 "오토코야마"의 양조 도구·고문서·우키요에를 전시하는 자료관.', '"연명장수의 물"이라 불리는 양조용 물을 무료로 마셔 볼 수 있고, 시음과 한정 상품 판매도 있다.', NULL, NULL, DATE '2026-11-22', NULL);
